import { hash, murmurHashOfSize } from './Hash';
import { IS_ORDERED_SYMBOL } from './predicates/isOrdered';
import { IS_KEYED_SYMBOL } from './predicates/isKeyed';
import { isOrderedMap } from './predicates/isOrderedMap';

export const ITERATE_KEYS = 0;
export const ITERATE_VALUES = 1;
export const ITERATE_ENTRIES = 2;

const REAL_ITERATOR_SYMBOL = typeof Symbol === 'function' && Symbol.iterator;
const FAUX_ITERATOR_SYMBOL = '@@iterator';

export const ITERATOR_SYMBOL = REAL_ITERATOR_SYMBOL || FAUX_ITERATOR_SYMBOL;

export class Iterator {
  constructor(next) {
    this.next = next;
  }

  toString() {
    return '[Iterator]';
  }

  hashCollection(collection) {
    if (collection.size === Infinity) {
      return 0;
    }

    const ordered = Boolean(collection[IS_ORDERED_SYMBOL]);
    const keyed = Boolean(collection[IS_KEYED_SYMBOL]);
    this._seed = ordered ? 1 : 0;

    const nestedMap = collection._map;
    const nestedList = collection._list;
    const mapSize = nestedMap ? nestedMap.size : undefined;
    const mapRoot = nestedMap ? nestedMap._root : undefined;
    const listOrigin = nestedList ? nestedList._origin : undefined;
    const listCapacity = nestedList ? nestedList._capacity : undefined;

    const useListEntries =
      isOrderedMap(collection) &&
      nestedList !== undefined &&
      listOrigin !== undefined &&
      listCapacity !== undefined;
    const useMapKeys =
      nestedMap !== undefined && !keyed && mapSize !== undefined;

    if (useListEntries) {
      nestedList.__iterate(entry => {
        if (entry) {
          this._seed =
            (31 * this._seed + hashMerge(hash(entry[1]), hash(entry[0]))) | 0;
        }
      });
      this._mixed = listCapacity - listOrigin;
    } else if (useMapKeys) {
      if (mapRoot || mapSize !== 0) {
        this._mixed = nestedMap.__iterate(value => {
          this._seed = ordered
            ? (31 * this._seed + hash(value)) | 0
            : (this._seed + hash(value)) | 0;
        });
      } else {
        this._mixed = mapSize;
      }
    } else {
      this._mixed = collection.__iterate(
        keyed
          ? ordered
            ? (v, k) => {
                this._seed =
                  (31 * this._seed + hashMerge(hash(v), hash(k))) | 0;
              }
            : (v, k) => {
                this._seed = (this._seed + hashMerge(hash(v), hash(k))) | 0;
              }
          : ordered
          ? v => {
              this._seed = (31 * this._seed + hash(v)) | 0;
            }
          : v => {
              this._seed = (this._seed + hash(v)) | 0;
            }
      );
    }

    return murmurHashOfSize(this._mixed, this._seed);
  }
}

function hashMerge(a, b) {
  return (a ^ (b + 0x9e3779b9 + (a << 6) + (a >> 2))) | 0; // int
}

Iterator.KEYS = ITERATE_KEYS;
Iterator.VALUES = ITERATE_VALUES;
Iterator.ENTRIES = ITERATE_ENTRIES;

Iterator.prototype.inspect = Iterator.prototype.toSource = function () {
  return this.toString();
};
Iterator.prototype[ITERATOR_SYMBOL] = function () {
  return this;
};

export function iteratorValue(type, k, v, iteratorResult) {
  const value = type === 0 ? k : type === 1 ? v : [k, v];
  iteratorResult
    ? (iteratorResult.value = value)
    : (iteratorResult = {
        value: value,
        done: false,
      });
  return iteratorResult;
}

export function iteratorDone() {
  return { value: undefined, done: true };
}

export function hasIterator(maybeIterable) {
  if (Array.isArray(maybeIterable)) {
    // IE11 trick as it does not support `Symbol.iterator`
    return true;
  }

  return !!getIteratorFn(maybeIterable);
}

export function isIterator(maybeIterator) {
  return maybeIterator && typeof maybeIterator.next === 'function';
}

export function getIterator(iterable) {
  const iteratorFn = getIteratorFn(iterable);
  return iteratorFn && iteratorFn.call(iterable);
}

function getIteratorFn(iterable) {
  const iteratorFn =
    iterable &&
    ((REAL_ITERATOR_SYMBOL && iterable[REAL_ITERATOR_SYMBOL]) ||
      iterable[FAUX_ITERATOR_SYMBOL]);
  if (typeof iteratorFn === 'function') {
    return iteratorFn;
  }
}

export function isEntriesIterable(maybeIterable) {
  const iteratorFn = getIteratorFn(maybeIterable);
  return iteratorFn && iteratorFn === maybeIterable.entries;
}

export function isKeysIterable(maybeIterable) {
  const iteratorFn = getIteratorFn(maybeIterable);
  return iteratorFn && iteratorFn === maybeIterable.keys;
}

